using System;

namespace RW3ProNativeDSHaptics;

/// <summary>
/// Controls ONLY commands generated by RW3. The real DualSense USB PCM reference
/// is NEVER multiplied, normalized, filtered or dynamically compressed here.
/// Nor can this control external games, Synapse, or native game XInput rumble.
/// </summary>
public static class HapticOutputLevel
{
    public const int DefaultPercent = 100;

    public static int Limit(int percent) => Math.Clamp(percent, 0, 100);

    public static float Apply(float value, int percent) =>
        float.IsFinite(value) ? value * (Limit(percent) / 100f) : 0f;

    public static double Apply(double value, int percent) =>
        double.IsFinite(value) ? value * (Limit(percent) / 100.0) : 0;
}
